-- Batch 7. Part 1 needs the build with spell_wcme_enchant_action (patch mystic-enchants-actions); part 2 works now.
-- Part 1: what each enchant does when it procs, read from its tooltip (see the patch for the columns). The
-- enchant spell is bound to the script, and its spell_proc row says which events can set it off.
DELETE FROM `spell_proc` WHERE `SpellId` IN (81408, 81467, 81526, 92247, 92249, 92250, 92252, 92438, 271778, 271997, 274179, 276302, 276361, 276397, 276669, 277746, 277790, 282134, 283584, 284475, 284711, 284716, 284752, 299938, 901048, 979137, 982375, 982567, 982572, 982605, 986084, 1587962, 1587982, 1588050);
-- Part 2: "while you have X, you also have Y" through the core's existing coa_mystic_enchant_aura_link table.
DELETE FROM `coa_mystic_enchant_aura_link` WHERE `enchant_spell` IN (283042, 283031, 272255, 272256, 281602, 281597, 299988, 271547, 276551, 272247, 275463, 299944, 271680, 1988300, 274179);
